template <typename T>
struct ChunkAlloc {
    using value_type = T;
    // std::deque allocates arrays (chunks) of size N*sizeof(T).
    T* allocate(size_t n) { /* Custom strategy (e.g., Fixed Pool) */
        return static_cast<T*>(malloc(n * sizeof(T)));
    }
    void deallocate(T* p, size_t n) { free(p); }
    // Required comparison for statefulness/propagation
    bool operator==(const ChunkAlloc&) const { return true; }
};

// Deque memory layout (multiple discontiguous chunks)
using PoolDeque = std::deque<long, ChunkAlloc<long>>;

PoolDeque d;
d.push_back(10); // Allocates first chunk via ChunkAlloc<long>.
